'use strict';
const $=s=>document.querySelector(s), money=n=>Math.round(n).toLocaleString('ru-RU')+' $', pct=n=>Math.round(n*100)+'%', KEY='meridian-save-v1';
const modes=[{name:'Фургон',icon:'▱',price:24000,cap:4,speed:650,fuel:.13,crew:55,maint:25,wear:2,region:0},{name:'Фура',icon:'▰',price:65000,cap:24,speed:750,fuel:.32,crew:100,maint:45,wear:2,region:0},{name:'Грузовой поезд',icon:'▤',price:240000,cap:180,speed:1000,fuel:1.1,crew:240,maint:140,wear:1,region:1},{name:'Контейнеровоз',icon:'≋',price:460000,cap:700,speed:850,fuel:2.6,crew:430,maint:220,wear:1,region:2},{name:'Грузовой самолёт',icon:'↗',price:620000,cap:90,speed:6000,fuel:3.3,crew:550,maint:320,wear:3,region:3},{name:'Перегон авто',icon:'↔',price:18000,cap:3,speed:900,fuel:.09,crew:80,maint:10,wear:2,region:0}];
const regions=[{name:'Европа',code:'EU',cities:['Берлин','Роттердам','Париж','Варшава'],cost:0,rep:0},{name:'Азия',code:'AS',cities:['Шанхай','Сингапур','Сеул','Мумбаи'],cost:95000,rep:30},{name:'Америка',code:'AM',cities:['Нью-Йорк','Хьюстон','Лос-Анджелес','Сан-Паулу'],cost:160000,rep:45},{name:'Африка',code:'AF',cities:['Каир','Кейптаун','Лагос','Касабланка'],cost:120000,rep:35},{name:'Океания',code:'OC',cities:['Сидней','Мельбурн','Окленд','Перт'],cost:210000,rep:55}];
const cargo=[{name:'Электроника',tag:'Техника',rate:1.3,license:null,modes:[0,1,2,3,4]},{name:'Продукты',tag:'Скоропортящийся',rate:1.55,license:'cold',modes:[0,1,2,3,4]},{name:'Металлы и руда',tag:'Ресурсы',rate:1,license:null,modes:[1,2,3]},{name:'Животные',tag:'Ветеринарный контроль',rate:1.8,license:'live',modes:[0,1,4]},{name:'Автомобили',tag:'Автоперевозка',rate:1.45,license:null,modes:[1,2,3,5]},{name:'Спецтехника',tag:'Негабарит',rate:1.7,license:'heavy',modes:[1,2,3]},{name:'Военная техника',tag:'Регулируемый груз',rate:2.1,license:'secure',modes:[2,3,4]},{name:'Промышленные детали',tag:'Промышленность',rate:1.2,license:null,modes:[0,1,2,3,4]}];
const research=[{id:'cold',name:'Холодовая цепь',cost:18000,rep:20,desc:'Перевозка продуктов. Просрочка снижает выплату ещё на 25%.'},{id:'live',name:'Ветеринарная лицензия',cost:26000,rep:25,desc:'Перевозка животных с повышенной оплатой и контролем.'},{id:'heavy',name:'Негабаритные перевозки',cost:35000,rep:30,desc:'Контракты на спецтехнику.'},{id:'secure',name:'Специальные разрешения',cost:90000,rep:55,desc:'Регулируемые контракты на военную технику.'},{id:'eco',name:'Экономичное вождение',cost:24000,rep:20,desc:'На 15% меньше расход топлива во всех рейсах.'},{id:'dispatch',name:'Цифровая диспетчерская',cost:48000,rep:35,desc:'На 20% быстрее доставка. Округление до полных дней.'},{id:'risk',name:'Контроль безопасности',cost:42000,rep:35,desc:'Риск происшествия в каждом рейсе ниже на 4 п.п.'}];
let state,tab='overview',filter='all',toastTimer;
function initial(){return {v:1,day:1,cash:180000,debt:0,rep:25,fuel:4500,fuelPrice:1.2,regions:[0],hubs:{0:1},tech:[],fleet:[{id:1,type:1,condition:100,location:0},{id:2,type:0,condition:100,location:0}],jobs:[],offers:[],ledger:[],history:[],logs:[],delivered:0,revenue:0,uid:10,event:{name:'Спокойный рынок',desc:'Базовые тарифы. Хороший момент для первых рейсов.',fuel:1,demand:1,risk:0}}}
function seed(n){const x=Math.sin(n*127.1+311.7)*43758.5453;return x-Math.floor(x)}
function generate(){state.offers=[];for(let i=0;i<14;i++){let g=i<3?[0,7,4][i]:Math.floor(seed(state.day*31+i)*cargo.length),r=state.regions[i%state.regions.length],d=i%5===4&&state.regions.length>1?state.regions[(i+1)%state.regions.length]:r,mode=cargo[g].modes[Math.floor(seed(i+state.day*11)*cargo[g].modes.length)];if(i===0)mode=0;if(i===1)mode=1;const dist=r!==d?6200+Math.round(seed(i+state.day)*5500):180+Math.round(seed(state.day*47+i)*2400),cap=modes[mode].cap,weight=Math.max(1,Math.round(cap*(.35+seed(i*8+state.day)*.6))),days=Math.ceil(dist/modes[mode].speed)+2,pay=Math.round((1800+dist*.56+Math.pow(weight,.73)*580)*cargo[g].rate*state.event.demand*(1+state.rep/500));state.offers.push({id:state.uid++,g,r,d,mode,dist,weight,pay,deadline:state.day+days,from:regions[r].cities[i%4],to:regions[d].cities[(i+1)%4]});}}
try{const saved=JSON.parse(localStorage.getItem(KEY));state=saved&&saved.v===1?saved:initial()}catch{state=initial()}if(!state.offers.length)generate();
function save(){try{localStorage.setItem(KEY,JSON.stringify(state))}catch{notify('Сохранение недоступно в этом браузере. Не закрывайте вкладку.')}}
function notify(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',3600)}
function log(t){state.logs.unshift({day:state.day,text:t});state.logs=state.logs.slice(0,60)}
function transaction(amount,type){state.cash+=amount;state.ledger.unshift({day:state.day,amount,type});state.ledger=state.ledger.slice(0,180)}
const busy=id=>state.jobs.some(j=>j.vehicle===id);
let fixed=()=>state.fleet.reduce((n,v)=>n+modes[v.type].crew+modes[v.type].maint,0)+state.regions.reduce((n,r)=>n+state.hubs[r]*85,0)+Math.ceil(state.debt*.001);
const capacity=r=>state.hubs[r]*200;
let load=r=>state.jobs.filter(j=>j.r===r).reduce((n,j)=>n+j.weight,0);
function quote(o,v,insured=true){const m=modes[v.type],fuel=Math.ceil(o.dist*m.fuel*(state.tech.includes('eco')?.85:1)),days=Math.max(1,Math.ceil(o.dist/m.speed*(state.tech.includes('dispatch')?.8:1))),toll=Math.round(o.pay*(o.r===o.d?.055:.12)),insurance=insured?Math.round(o.pay*.05):0,risk=Math.max(.01,.035+(100-v.condition)/450+state.event.risk-(state.tech.includes('risk')?.04:0)),cost=fuel*state.fuelPrice+toll+insurance+(m.crew+m.maint)*days;return{fuel,days,toll,insurance,risk,cost,margin:o.pay-cost}}
function canVehicle(o,v){return !busy(v.id)&&v.condition>=30&&v.location===o.r&&cargo[o.g].modes.includes(v.type)&&modes[v.type].cap>=o.weight&&(o.r===o.d||[3,4].includes(v.type))}
function openTab(t){tab=t;render()}
function header(){return `<header><div class="brand"><span class="mark">M</span> MERIDIAN <span class="eyebrow" style="margin-left:16px">GLOBAL LOGISTICS</span></div><button onclick="help()">? <span class="desktop">Как играть</span></button></header><div class="shell"><aside><div class="eyebrow" style="padding:0 12px 18px">Центр управления</div><nav>${[['overview','◫','Обзор'],['contracts','▤','Контракты'],['fleet','▱','Транспорт'],['network','⌘','Сеть и склады'],['research','◇','Развитие'],['finance','↗','Финансы']].map(([id,icon,name])=>`<button class="${tab===id?'active':''}" onclick="openTab('${id}')"><span>${icon}</span>${name}</button>`).join('')}</nav><div class="sidefoot"><div class="badge green">Локальная кампания</div><p>Автосохранение на этом устройстве</p><div class="split"></div>MERIDIAN / ECONOMY v2.0</div></aside><main class="main"><div class="topline"><div><div class="eyebrow">Операционный день ${String(state.day).padStart(3,'0')}</div><h1>${{overview:'Ваш мир в движении',contracts:'Биржа контрактов',fleet:'Транспортный парк',network:'Глобальная сеть',research:'Технологии и лицензии',finance:'Финансы компании'}[tab]}</h1><p>${{overview:'Каждый маршрут — экономическое решение.',contracts:'Выбирайте груз, считайте маржу, отправляйте рейсы.',fleet:'Вместимость, скорость и расходы имеют значение.',network:'Открывайте рынки и увеличивайте пропускную способность.',research:'Новые грузы и эффективность вашей сети.',finance:'Ликвидность сегодня. Масштаб завтра.'}[tab]}</p></div><div class="inline"><span class="badge">Пошаговая стратегия</span><button class="primary" onclick="nextDay()">Завершить день →</button></div></div><div class="stats"><div class="stat"><small>Доступные средства</small><div class="value">${money(state.cash)}</div><small>Обязательства: ${money(state.debt)}</small></div><div class="stat"><small>В рейсе / всего транспорта</small><div class="value">${state.jobs.length} <span class="muted">/ ${state.fleet.length}</span></div><small>${state.fleet.length-state.jobs.length} ед. свободно</small></div><div class="stat"><small>Репутация компании</small><div class="value">${state.rep} <span class="muted">/ 100</span></div><small>${state.rep<40?'Региональный оператор':state.rep<70?'Международный перевозчик':'Глобальный оператор'}</small></div><div class="stat"><small>Постоянные расходы / день</small><div class="value">${money(fixed())}</div><small>Штат, парк, склады и проценты</small></div></div>`}
function offerTable(items){return `<div class="tablewrap"><table><thead><tr><th>ГРУЗ / МАРШРУТ</th><th>ОБЪЁМ</th><th>ВЫПЛАТА</th><th>СРОК</th><th></th></tr></thead><tbody>${items.map(o=>`<tr><td><strong>${cargo[o.g].name}</strong><small>${o.from} → ${o.to} · ${o.dist.toLocaleString('ru-RU')} км</small></td><td>${o.weight} т<small>${modes[o.mode].name}</small></td><td class="positive">${money(o.pay)}</td><td>${o.deadline-state.day} дн.</td><td><button onclick="contract(${o.id})">Рассчитать ↗</button></td></tr>`).join('')}</tbody></table></div>`}
function jobs(){return state.jobs.length?state.jobs.map(j=>`<div class="card"><div class="row"><h3>${cargo[j.g].name}</h3><span class="badge green">${j.trade?'Свой товар':j.returning?'Возврат':j.reposition?'Перебазирование':'В пути'}</span></div><div class="route"><b>${j.from}</b><em></em><span>→</span><em></em><b>${j.to}</b></div><div class="progress"><i style="width:${100*(1-j.remaining/j.total)}%"></i></div><div class="row"><small>Ещё ${j.remaining} дн. · ${modes[state.fleet.find(v=>v.id===j.vehicle).type].name}</small><strong class="positive">${j.returning||j.reposition?'—':money(j.pay)}</strong></div></div>`).join(''):'<div class="empty">Пока нет активных рейсов.<br>Рассчитайте контракт и отправьте первый груз.</div>'}
function overview(){return `${!state.delivered&&!state.jobs.length?'<div class="callout"><strong>Первый рейс.</strong> Начните с электроники или промышленных деталей. Фургон и фура уже в вашем парке. Оплата поступит после доставки.</div>':''}<div class="cols"><section><div class="panel"><div class="row"><h2>Доступные контракты <span class="badge">${state.offers.length}</span></h2><button onclick="openTab('contracts')">Все заказы →</button></div>${offerTable(state.offers.slice(0,4))}</div><div class="panel"><div class="row"><h2>Активные перевозки</h2><small>${state.jobs.length} рейсов</small></div><div class="grid" style="margin-top:18px">${jobs()}</div></div></section><section><div class="panel"><div class="eyebrow">Рыночная сводка</div><h2 style="margin-top:12px">${state.event.name}</h2><p style="font-size:14px">${state.event.desc}</p><div class="metric"><span>Топливо</span><strong>${state.fuelPrice.toFixed(2)} $ / л</strong></div><div class="metric"><span>Тарифный индекс</span><strong class="positive">×${state.event.demand.toFixed(2)}</strong></div><div class="metric"><span>Следующая сводка</span><span>через ${5-(state.day-1)%5} дн.</span></div></div><div class="panel"><div class="row"><h2>Топливный резерв</h2><span class="blue">${state.fuel.toLocaleString('ru-RU')} л</span></div><p style="font-size:14px">Топливо списывается при отправке. Можно закупать заранее.</p><button style="width:100%;margin-top:12px" onclick="buyFuel(1000)">+ 1 000 л · ${money(state.fuelPrice*1000)}</button></div><div class="banner"><div class="eyebrow">Масштаб компании</div><div class="metric"><span>Доставлено грузов</span><strong>${state.delivered}</strong></div><div class="metric"><span>Рынков открыто</span><strong>${state.regions.length} / 5</strong></div><div class="metric"><span>Выручка за всё время</span><strong>${money(state.revenue)}</strong></div></div></section></div>`}
function contracts(){const items=state.offers.filter(o=>filter==='all'||filter==='ready'&&state.fleet.some(v=>canVehicle(o,v))&&(!cargo[o.g].license||state.tech.includes(cargo[o.g].license))||filter==='special'&&cargo[o.g].license);return `<div class="tabs">${[['all','Все контракты'],['ready','Под мой парк'],['special','Специальные грузы']].map(([id,n])=>`<button class="${filter===id?'active':''}" onclick="filter='${id}';render()">${n}</button>`).join('')}<small style="align-self:center;margin-left:auto">Биржа обновляется каждый день</small></div><div class="panel">${items.length?offerTable(items):'<div class="empty">Подходящих заказов нет. Развивайте парк или дождитесь следующего дня.</div>'}</div><h2 style="margin:24px 0 16px">В пути</h2><div class="grid">${jobs()}</div>`}
function fleet(){return `<div class="panel"><div class="row"><h2>Ваш парк</h2><span class="badge">${state.fleet.length} ед.</span></div><div class="grid" style="margin-top:18px">${state.fleet.map(v=>`<div class="card"><div class="row"><div class="inline"><span class="transport">${modes[v.type].icon}</span><h3>${modes[v.type].name} #${v.id}</h3></div><span class="badge ${busy(v.id)?'':'green'}">${busy(v.id)?'В рейсе':'Свободен'}</span></div><p>${regions[v.location].name} · ${modes[v.type].cap} т · ${money(modes[v.type].crew+modes[v.type].maint)}/день</p><div class="metric"><span>Состояние</span><strong class="${v.condition<40?'negative':'positive'}">${v.condition}%</strong></div><div class="progress"><i style="width:${v.condition}%"></i></div><div class="inline"><button ${busy(v.id)||v.condition===100?'disabled':''} onclick="repair(${v.id})">Ремонт · ${money(repairCost(v))}</button><button ${busy(v.id)?'disabled':''} onclick="relocate(${v.id})">Перебазировать</button><button ${busy(v.id)?'disabled':''} onclick="sell(${v.id})">Продать</button></div></div>`).join('')}</div></div><h2 style="margin:26px 0 16px">Купить транспорт</h2><div class="grid">${modes.map((m,i)=>`<div class="card"><div class="row"><span class="transport">${m.icon}</span><span class="badge">${m.cap} т</span></div><h3>${m.name}</h3><div class="metric"><span>Скорость</span><span>${m.speed} км/день</span></div><div class="metric"><span>Расход топлива</span><span>${m.fuel} л/км</span></div><div class="metric"><span>Содержание</span><span>${money(m.crew+m.maint)}/день</span></div><div class="row"><strong>${money(m.price)}</strong><button class="primary" ${state.cash<m.price?'disabled':''} onclick="buyVehicle(${i})">Купить</button></div><small>Базирование: Европа${i===5?' · только автомобили':''}</small></div>`).join('')}</div>`}
function network(){return `<div class="callout">Склад ограничивает запасы, контрактные грузы и ожидаемые товарные поставки. Межконтинентальные рейсы выполняют самолёты и суда. После доставки транспорт остаётся в регионе назначения.</div><div class="grid">${regions.map((r,i)=>{const open=state.regions.includes(i);return `<div class="card"><div class="row"><span class="eyebrow">${r.code} / РЫНОК ${i+1}</span><span class="badge ${open?'green':''}">${open?'Открыт':'Новый рынок'}</span></div><h2>${r.name}</h2><p>${r.cities.join(' · ')}</p>${open?`<div class="metric"><span>Складской узел</span><strong>Уровень ${state.hubs[i]}</strong></div><div class="metric"><span>Зарезервировано</span><span>${load(i).toFixed(1)} / ${capacity(i)} т</span></div><div class="progress"><i style="width:${load(i)/capacity(i)*100}%"></i></div><div class="metric"><span>Содержание</span><span>${money(state.hubs[i]*85)}/день</span></div><button style="width:100%;margin-top:16px" onclick="upgradeHub(${i})">+ 200 т · ${money(state.hubs[i]*18000)}</button>`:`<div class="metric"><span>Нужна репутация</span><span>${r.rep}</span></div><p>Открывает контракты региона и склад на 200 т.</p><div class="row"><strong>${money(r.cost)}</strong><button class="primary" ${state.rep<r.rep||state.cash<r.cost?'disabled':''} onclick="openRegion(${i})">Открыть</button></div>`}</div>`}).join('')}</div>`}
function development(){return `<div class="grid">${research.map(t=>`<div class="card"><div class="row"><span class="eyebrow">${['cold','live','heavy','secure'].includes(t.id)?'Доступ к грузам':'Эффективность'}</span>${state.tech.includes(t.id)?'<span class="badge green">Активно</span>':'<span class="badge">Репутация '+t.rep+'</span>'}</div><h3>${t.name}</h3><p style="min-height:44px">${t.desc}</p><div class="row"><strong>${money(t.cost)}</strong><button class="${state.tech.includes(t.id)?'':'primary'}" ${state.tech.includes(t.id)||state.cash<t.cost||state.rep<t.rep?'disabled':''} onclick="researchTech('${t.id}')">${state.tech.includes(t.id)?'Внедрено':'Внедрить'}</button></div></div>`).join('')}</div>`}
function finances(){const limit=creditLimit();return `<div class="cols"><section><div class="panel"><h2>Денежный поток</h2><p>Остаток на конец дня · последние 20 дней</p><div class="spark">${(state.history.length?state.history:[state.cash]).slice(-20).map(n=>`<i title="${money(n)}" style="height:${Math.max(3,n/Math.max(1,...state.history,state.cash)*100)}%"></i>`).join('')}</div><div class="metric"><span>Стоимость парка при продаже</span><strong>${money(state.fleet.reduce((n,v)=>n+sellPrice(v),0))}</strong></div><div class="metric"><span>Ожидаемые выплаты за рейсы</span><strong>${money(state.jobs.reduce((n,j)=>n+(j.reposition?0:j.pay),0))}</strong></div><div class="metric"><span>Проценты в день</span><strong>${money(Math.ceil(state.debt*.001))}</strong></div></div><div class="panel"><h2>Журнал операций</h2><div class="tablewrap"><table><thead><tr><th>ДЕНЬ</th><th>ОПЕРАЦИЯ</th><th>СУММА</th></tr></thead><tbody>${state.ledger.slice(0,25).map(l=>`<tr><td>${l.day}</td><td>${l.type}</td><td class="${l.amount>0?'positive':'negative'}">${l.amount>0?'+':''}${money(l.amount)}</td></tr>`).join('')||'<tr><td colspan="3">Операций пока нет</td></tr>'}</tbody></table></div></div></section><section><div class="panel"><h2>Кредитная линия</h2><p style="font-size:14px">0,1% в день. Лимит зависит от репутации и стоимости парка. Погашение — по вашему решению.</p><div class="metric"><span>Долг</span><strong>${money(state.debt)}</strong></div><div class="metric"><span>Доступно</span><strong>${money(Math.max(0,limit-state.debt))}</strong></div><div class="inline" style="margin-top:18px"><button onclick="loan()" ${limit-state.debt<25000?'disabled':''}>Взять 25 000 $</button><button onclick="repay()" ${!state.debt||state.cash<=0?'disabled':''}>Погасить до 25 000 $</button></div></div><div class="panel"><h2>Закупка топлива</h2><p>${state.fuel.toLocaleString('ru-RU')} л в резерве · ${state.fuelPrice.toFixed(2)} $/л</p><div class="inline"><button onclick="buyFuel(1000)">1 000 л</button><button onclick="buyFuel(10000)">10 000 л</button></div></div><div class="panel"><h2>События компании</h2>${state.logs.slice(0,8).map(l=>`<div class="log"><small>Д${l.day}</small>${l.text}</div>`).join('')||'<p>История начинается с первого рейса.</p>'}</div><button onclick="resetGame()">Новая кампания</button></section></div>`}
function render(){ $('#app').innerHTML=header()+({overview,contracts,fleet,network,research:development,finance:finances}[tab])()+'</main></div>';save() }
function modal(html){$('#modal').innerHTML=html;$('#modal').showModal()}
function closeModal(){$('#modal').close()}
function contract(id){const o=state.offers.find(o=>o.id===id);if(!o)return;const license=cargo[o.g].license,vehicles=state.fleet.filter(v=>canVehicle(o,v));modal(`<div class="row"><h2>${cargo[o.g].name}</h2><button onclick="closeModal()" aria-label="Закрыть">×</button></div><div class="route"><b>${o.from}</b><em></em>→<em></em><b>${o.to}</b></div><p>${o.weight} т · ${o.dist} км · доставить за ${o.deadline-state.day} дней</p>${license&&!state.tech.includes(license)?`<div class="callout">Нужно разрешение: ${research.find(t=>t.id===license).name}.</div>`:''}<label for="vehicle">Транспорт из региона отправления</label><select id="vehicle" onchange="updateQuote(${id})">${vehicles.length?vehicles.map(v=>`<option value="${v.id}">${modes[v.type].name} #${v.id} · ${v.condition}% · ${modes[v.type].cap} т</option>`).join(''):'<option value="">Нет подходящего свободного транспорта</option>'}</select><label class="inline"><input type="checkbox" id="insurance" checked onchange="updateQuote(${id})"> Страхование груза · 5% выплаты</label><div id="quote"></div><div class="actions"><button onclick="closeModal()">Отмена</button><button id="send" class="primary" onclick="dispatch(${id})">Отправить груз →</button></div>`);updateQuote(id)}
function updateQuote(id){const o=state.offers.find(o=>o.id===id),v=state.fleet.find(v=>v.id===Number($('#vehicle').value));if(!v){$('#quote').innerHTML='<p>Купите транспорт нужной вместимости, дождитесь возвращения или перебазируйте его.</p>';$('#send').disabled=true;return}const q=quote(o,v,$('#insurance').checked),need=Math.max(0,q.fuel-state.fuel),now=need*state.fuelPrice+q.toll+q.insurance,missing=cargo[o.g].license&&!state.tech.includes(cargo[o.g].license),full=load(o.r)+o.weight>capacity(o.r);$('#quote').innerHTML=`<div class="split"></div><div class="metric"><span>Выплата при доставке</span><strong class="positive">${money(o.pay)}</strong></div><div class="metric"><span>Топливо: ${q.fuel} л</span><span>${money(q.fuel*state.fuelPrice)}</span></div><div class="metric"><span>Сборы + страхование</span><span>${money(q.toll+q.insurance)}</span></div><div class="metric"><span>Штат и содержание в пути</span><span>${money((modes[v.type].crew+modes[v.type].maint)*q.days)}</span></div><div class="metric"><strong>Плановая маржа</strong><strong class="${q.margin>0?'positive':'negative'}">${money(q.margin)}</strong></div><p>В пути ${q.days} дн. · риск происшествия ${pct(q.risk)}. При происшествии: +2 дня, без страховки −30% выплаты.</p><p>Сейчас спишется ${money(now)}${need?' (включая докупку '+need+' л)':''}. Резерв топлива учтён в марже по текущей цене. Общие расходы складов и проценты не включены.</p>${state.day+q.days>o.deadline?'<p class="negative">Рейс прибудет позже срока: −8% выплаты за каждый день, до 40%.</p>':''}${full?'<p class="negative">Не хватает складской мощности. Расширьте узел.</p>':''}`;$('#send').disabled=!!(missing||full||state.cash<now)}
function dispatch(id){const o=state.offers.find(x=>x.id===id),v=state.fleet.find(x=>x.id===Number($('#vehicle').value));if(!o||!v||!canVehicle(o,v))return;const insured=$('#insurance').checked,q=quote(o,v,insured),need=Math.max(0,q.fuel-state.fuel),cost=need*state.fuelPrice+q.toll+q.insurance;if(state.cash<cost||load(o.r)+o.weight>capacity(o.r)||cargo[o.g].license&&!state.tech.includes(cargo[o.g].license))return;transaction(-cost,'Отправка: '+cargo[o.g].name);state.fuel+=need-q.fuel;state.jobs.push({...o,vehicle:v.id,remaining:q.days,total:q.days,insured,risk:q.risk,incident:false});state.offers=state.offers.filter(x=>x.id!==id);log('Груз отправлен: '+o.from+' → '+o.to);closeModal();render();notify('Рейс отправлен. Завершайте дни, чтобы доставить груз.')}
const events=[{name:'Спокойный рынок',desc:'Стабильные тарифы и обычная стоимость топлива.',fuel:1,demand:1,risk:0},{name:'Сезон высокого спроса',desc:'Заказчики платят на 25% больше. Топливо подорожало на 12%.',fuel:1.12,demand:1.25,risk:.01},{name:'Топливный дефицит',desc:'Топливо дороже на 40%. Резервы помогают сохранить маржу.',fuel:1.4,demand:1.12,risk:0},{name:'Сложная погода',desc:'Риск происшествий выше на 6 п.п. Страхование особенно полезно.',fuel:1.05,demand:1.18,risk:.06},{name:'Промышленный спад',desc:'Тарифы ниже на 15%, топливо дешевле на 18%.',fuel:.82,demand:.85,risk:0}];
function nextDay(){state.day++;transaction(-fixed(),'Штат, содержание и проценты');const done=[];for(const j of state.jobs){j.remaining--;const v=state.fleet.find(v=>v.id===j.vehicle);if(!j.incident&&!j.reposition&&j.remaining===0&&seed(j.id*71+j.deadline)<j.risk){j.incident=true;j.remaining=2;j.total+=2;log('Задержка рейса '+j.from+' → '+j.to+' на 2 дня');continue}if(j.remaining<=0){if(!j.reposition){const late=Math.max(0,state.day-j.deadline),penalty=Math.min(.4,late*.08)+(j.g===1&&late?.25:0),damage=j.incident&&!j.insured?.3:0,pay=Math.round(j.pay*Math.max(.05,1-penalty-damage));transaction(pay,'Доставка: '+cargo[j.g].name);state.revenue+=pay;state.delivered++;state.rep=Math.min(100,Math.max(0,state.rep+(late?-4:2)));log('Доставлено: '+cargo[j.g].name+' · '+money(pay));}else if(!j.trade)log('Перебазирование завершено');v.location=j.d;v.condition=Math.max(0,v.condition-Math.ceil(j.dist/600)*modes[v.type].wear-(j.incident?7:0));done.push(j.id)}}state.jobs=state.jobs.filter(j=>!done.includes(j.id));if((state.day-1)%5===0){state.event=events[Math.floor(seed(state.day*3)*events.length)];log(state.event.name)}state.fuelPrice=Math.round(120*state.event.fuel*(.96+seed(state.day)*.08))/100;generate();state.history.push(state.cash);state.history=state.history.slice(-60);render();if(state.cash<0)notify('Кассовый разрыв: возьмите кредит или продайте свободный транспорт.');else notify(done.length?'День '+state.day+': завершено рейсов — '+done.length:'Наступил день '+state.day)}
function spend(n,desc){if(state.cash<n){notify('Недостаточно средств');return false}transaction(-n,desc);return true}
function buyFuel(n){if(spend(n*state.fuelPrice,'Закупка '+n+' л топлива')){state.fuel+=n;render();notify('Топливный резерв пополнен')}}
function buyVehicle(type){if(!modes[type])return;if(spend(modes[type].price,'Покупка: '+modes[type].name)){state.fleet.push({id:state.uid++,type,condition:100,location:0});render();notify('Транспорт добавлен в парк')}}
const repairCost=v=>Math.round(modes[v.type].price*(100-v.condition)*.002),sellPrice=v=>Math.round(modes[v.type].price*.65*v.condition/100);
function repair(id){const v=state.fleet.find(x=>x.id===id);if(!v||busy(id))return;if(spend(repairCost(v),'Ремонт транспорта #'+id)){v.condition=100;render();notify('Ремонт завершён')}}
function sell(id){const v=state.fleet.find(x=>x.id===id);if(!v||busy(id))return;modal(`<h2>Продать ${modes[v.type].name} #${id}?</h2><p>В компанию поступит ${money(sellPrice(v))}. Ежедневные расходы сократятся на ${money(modes[v.type].crew+modes[v.type].maint)}.</p><div class="actions"><button onclick="closeModal()">Отмена</button><button class="primary" onclick="confirmSell(${id})">Продать</button></div>`)}
function confirmSell(id){const v=state.fleet.find(x=>x.id===id);if(!v||busy(id))return;transaction(sellPrice(v),'Продажа транспорта');state.fleet=state.fleet.filter(x=>x.id!==id);closeModal();render()}
function relocate(id){const v=state.fleet.find(v=>v.id===id);if(!v||busy(id))return;const opts=state.regions.filter(r=>r!==v.location);modal(`<h2>Перебазировать транспорт</h2><p>Международная перевозка транспортной единицы: ${money(modes[v.type].price*.035)}. Занимает 3 дня, без дополнительного списания топлива.</p>${opts.length?`<select id="destination">${opts.map(r=>`<option value="${r}">${regions[r].name}</option>`).join('')}</select>`:'<p>Сначала откройте второй рынок в разделе «Сеть и склады».</p>'}<div class="actions"><button onclick="closeModal()">Отмена</button><button class="primary" ${opts.length?'':'disabled'} onclick="confirmRelocate(${id})">Перебазировать</button></div>`)}
function confirmRelocate(id){const v=state.fleet.find(v=>v.id===id),d=Number($('#destination').value);if(!v||busy(id)||!state.regions.includes(d)||d===v.location)return;if(spend(modes[v.type].price*.035,'Перебазирование')){state.jobs.push({id:state.uid++,vehicle:id,g:7,r:v.location,d,from:regions[v.location].name,to:regions[d].name,weight:0,pay:0,dist:0,remaining:3,total:3,reposition:true});closeModal();render()}}
function openRegion(r){const x=regions[r];if(!x||state.regions.includes(r)||state.rep<x.rep)return;if(spend(x.cost,'Открытие рынка: '+x.name)){state.regions.push(r);state.hubs[r]=1;generate();render();notify('Открыт рынок: '+x.name)}}
function upgradeHub(r){if(!state.regions.includes(r))return;if(spend(state.hubs[r]*18000,'Расширение склада: '+regions[r].name)){state.hubs[r]++;render();notify('Вместимость увеличена на 200 т')}}
function researchTech(id){const t=research.find(t=>t.id===id);if(!t||state.tech.includes(id)||state.rep<t.rep)return;if(spend(t.cost,t.name)){state.tech.push(id);render();notify('Внедрено: '+t.name)}}
function creditLimit(){return Math.round((state.rep*2000+state.fleet.reduce((n,v)=>n+sellPrice(v)*.5,0))/1000)*1000}
function loan(){if(creditLimit()-state.debt<25000)return;state.debt+=25000;transaction(25000,'Получение кредита');render();notify('Кредит зачислен. Проценты включены в ежедневные расходы.')}
function repay(){const amount=Math.min(25000,state.debt,Math.max(0,state.cash));if(!amount)return;state.debt-=amount;transaction(-amount,'Погашение кредита');render()}
function resetGame(){modal('<h2>Начать новую кампанию?</h2><p>Текущий прогресс на этом устройстве будет удалён.</p><div class="actions"><button onclick="closeModal()">Отмена</button><button onclick="state=initial();generate();tab=\'overview\';closeModal();render()">Начать заново</button></div>')}
function help(){modal(`<div class="row"><h2>Постройте сеть. Сохраните маржу.</h2><button aria-label="Закрыть" onclick="closeModal()">×</button></div><div class="help"><p><strong>1. Рассчитайте первый рейс.</strong> В начале у вас 180 000 $, фургон, фура и 4 500 л топлива. На бирже выберите электронику или промышленные детали.</p><p><strong>2. Сравните выплату и расходы.</strong> Топливо, сборы и страховка оплачиваются при отправке. Зарплаты, содержание и проценты — каждый день, даже когда парк простаивает.</p><p><strong>3. Завершайте дни.</strong> Время движется только по кнопке. Выплата поступает при доставке. Просрочка: −8% за день, максимум −40%; продукты теряют ещё 25%.</p><p><strong>4. Управляйте риском.</strong> Износ увеличивает вероятность задержки. Страховка покрывает потерю 30% груза, но не штраф за просрочку. Ниже 30% состояния нужен ремонт.</p><p><strong>5. Расширяйте компанию.</strong> Репутация растёт на 2 за своевременную доставку и падает на 4 за просрочку. Открывайте лицензии, рынки и склады, покупайте поезда, суда и самолёты.</p><p><strong>6. Следите за оборотными деньгами.</strong> Кредиты стоят 0,1% в день. При отрицательном балансе продолжатся расходы: используйте кредит, дождитесь выплат или продайте технику.</p><p>После рейса транспорт остаётся в регионе назначения. Межконтинентальные грузы перевозятся морем или по воздуху. Перегон авто работает только с автомобилями.</p><p>Кампания сохраняется автоматически в этом браузере. Все цены и события — условные игровые величины.</p></div><div class="actions"><button class="primary" onclick="closeModal()">К управлению →</button></div>`)}
render();
if(document.modelContext?.registerTool){try{document.modelContext.registerTool({name:'read_logistics_company',description:'Read the current local logistics game company, fleet and active shipments.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({day:state.day,cash:state.cash,debt:state.debt,reputation:state.rep,fleet:state.fleet,jobs:state.jobs})})}catch{}}
